@startuml

enum Suit {
  Diamonds
  Hearts
  Spades
  Clubs
}

enum SoloType {
  Trump
  Jack
  Queen
}

enum RoundType {
  JackRound
  SoloRound
  MandatorySoloRound
}

abstract class Card {
  + id : int
  + height : int
  + suit : Suit

  + compareTo(otherCard : Card) : string
}

class Deck {
  + id : int
  + cards : Card[]

  + draw() : Card
}

class ScoringTable {
  + id : int
  + rounds : Round[]
}

abstract class Round {
  + id : int
  + winningPlayers : Player[]
  + pointValue : int
  + roundType : RoundType
}

class JackRound extends Round {}

class SoloRound extends Round {
  + soloType : SoloType
  + soloPlayer : Player
}

class MandatorySoloRound extends SoloRound {}

abstract class Player {
  + id : int
  + name : string
}

class Game {
  + id : int
  + players : Player[]
  + deck : Deck
  + scoringTable : ScoringTable
}

Card "0..*" -- "1" Deck : belongsTo
ScoringTable "0..*" -- "1" Round : contains
Round "0..*" -- "0..*" Player : involves

@enduml

